import{renderCustomModel}from './visual.js?v=20261023-physicscomplete01';import{buildSpecial}from './special-infection-meshes.js?v=20261023-physicscomplete01';import{specialFigure}from './special-infection-figures.js?v=20261023-physicscomplete01';
export function showSpecial(scene,w={}){let[kind,state]=scene.split(':'),names={fusion:'One clone, many identical products',binding:'One binding specificity',assay:'Turn binding into a signal',symptoms:'A sign is a starting point',evidence:'Choose identification evidence',nutrient:'Different ions, different roles',plant:'Different causes of plant damage',barrier:'Resist entry at the surface',chemical:'A chemical and its target',mechanical:'Change what an animal encounters'},o={kind,state:state||'parents',revealed:true,...w},name=w.title||names[kind]||'Investigate the mechanism';renderCustomModel({name,formula:w.stateLabel||'Inspect; switch to the labelled diagram',kicker:'SCHEMATIC BIOLOGY MODEL',aria:name+'. Symbolic shapes/scales; labelled diagram available.',atoms:[],bonds:[],radius:2.5,viewKey:'special-'+kind,startPaused:true,note:'Original schematic · not a diagnostic specimen',diagram:specialFigure({...o,title:name}),build:(g,T)=>buildSpecial(g,T,o)});}
